function init(){
  document.getElementById('chipAllCount').textContent = DATA.length;
  document.getElementById('crumbCur').textContent = state.theme?('主題 · '+state.theme):'全部作品';
  render();
  document.getElementById('search').addEventListener('input',e=>{state.q=e.target.value.trim().toLowerCase();state.page=1;const act=document.querySelector('.tab.active');if(act&&act.dataset.page!=='products'&&act.dataset.page!=='print'){if(act.dataset.page==='ceramist'){renderCeramist();return;}renderCustom(act.dataset.page);return;}render();});
  document.getElementById('catSel').addEventListener('change',e=>{const v=e.target.value;if(v.indexOf('__lib_')===0){switchPage(v.slice(6));e.target.value='';return;}state.cat=v;state.page=1;render();});
  document.querySelectorAll('#chips .chip').forEach(c=>{
    c.onclick=()=>{state.top='';state.sub='';state.theme=c.dataset.theme||'';state.page=1;
      document.querySelectorAll('#chips .chip').forEach(x=>x.classList.remove('active'));
      document.querySelectorAll('#chips .chip-lib').forEach(x=>x.classList.remove('active'));
      c.classList.add('active');
      document.getElementById('crumbCur').textContent = state.theme?('主題 · '+state.theme):'全部作品';
      render();};
  });
  const closeMega=()=>document.querySelectorAll('.has-mega.open').forEach(h=>h.classList.remove('open'));
  document.querySelectorAll('.mega-toggle').forEach(a=>{
    a.onclick=e=>{e.preventDefault();
      const h=a.closest('.has-mega');
      const was=h.classList.contains('open');
      closeMega();
      if(!was) h.classList.add('open');
    };
  });
  document.querySelectorAll('.mega-item').forEach(a=>{
    a.onclick=e=>{e.preventDefault();closeMega();
      if(a.dataset.goto){switchPage(a.dataset.goto);return;}
      applyCat(a.dataset.top||'',a.dataset.sub||'',a.dataset.theme||'');};
  });
  document.addEventListener('click',e=>{ if(!e.target.closest('.has-mega')) closeMega(); });
  document.querySelectorAll('#chips .chip-lib').forEach(c=>{
    c.querySelector('em').textContent = c.dataset.goto==='archive'?ARCHIVE_DATA.length:customFiles(c.dataset.goto).list.length;
    c.onclick=()=>{document.querySelectorAll('#chips .chip').forEach(x=>x.classList.remove('active'));c.classList.add('active');switchPage(c.dataset.goto);};
  });
  document.querySelectorAll('.mega-item[data-goto]').forEach(a=>{if(a.dataset.goto==='print'){a.querySelector('.mega-count').textContent=PRINT_FILES.length+' 件';return;}if(a.dataset.goto==='products'){a.querySelector('.mega-count').textContent=DATA.length+' 件';return;}
if(a.dataset.goto==='ceramist'){a.querySelector('.mega-count').textContent=CERAMIST_ITEMS.length+' 件';return;}
if(a.dataset.goto==='archive'){a.querySelector('.mega-count').textContent=ARCHIVE_DATA.length+' 件';return;}const f=customFiles(a.dataset.goto);if(f&&f.list)a.querySelector('.mega-count').textContent=f.list.length+' 件';});
  const megaSel=document.getElementById('megaCeramistSel');
  if(megaSel){
    megaSel.innerHTML='<option value="">陶藝家 ▾</option>'+CERAMIST_ARTISTS.map(a=>'<option value="'+a.n+'">'+a.n+'（'+a.c+'）</option>').join('');
    megaSel.onchange=()=>{const v=megaSel.value;megaSel.value='';ceramistFilter=v;switchPage('ceramist');ceramistFilter=v;renderCeramist();closeMega();document.getElementById('ceramistPage').scrollIntoView({behavior:'smooth',block:'start'});};
  }
  const cSel=document.getElementById('ceramistSel');
  if(cSel){
    cSel.innerHTML='<option value="">藝家 ▾</option>'+CERAMIST_ARTISTS.map(a=>'<option value="'+a.n+'">'+a.n+'（'+a.c+'）</option>').join('');
    cSel.onchange=()=>{const v=cSel.value;cSel.value='';ceramistFilter=v;renderCeramist();const box=document.getElementById('ceramistChips');box.querySelectorAll('.chip').forEach(x=>x.classList.remove('active'));const t=box.querySelector('.chip[data-artist="'+v+'"]');if(t)t.classList.add('active');};
  }

}
function applyCat(top,sub,theme){
  state.top=top;state.sub=sub;state.theme=theme||'';state.page=1;
  document.querySelectorAll('#chips .chip').forEach(x=>x.classList.remove('active'));
  const lbl = theme ? ('主題 · '+theme) : (top?(sub?(top+' / '+sub):top):'全部作品');
  document.getElementById('crumbCur').textContent = lbl;
  document.querySelectorAll('.mega-item').forEach(a=>{a.classList.toggle('active',a.dataset.top===top && a.dataset.sub===(sub||''));});
  document.getElementById('browse').scrollIntoView({behavior:'smooth'});
  render();
}
function matchOfficial(d,top,sub){
  if(!top) return true;
  const subs = sub? [sub] : [''];
  const cats = d.officialCats||[];
  if(sub){
    return cats.some(c=>c[0]===top && c[1]===sub);
  }
  return cats.some(c=>c[0]===top);
}
function getFiltered(){
  let list = DATA.filter(d=>{
    if(state.top && !matchOfficial(d,state.top,state.sub)) return false;
    if(state.theme && d.theme!==state.theme) return false;
    if(state.cat && d.cat!==state.cat) return false;
    if(state.stock){
      const n=parseInt(d.stock,10);
      if(isNaN(n) || n < state.stock) return false;
    }
    if(state.q){
      const hay = [d.pid,d.prodName,d.prodPrice,d.stock,d.dims,d.launchYear,d.theme,
        (d.themeTags||[]).join(' '),d.officialCat,d.officialSub].join(' ').toLowerCase();
      if(!hay.includes(state.q)) return false;
    }
    if(state.sort==='missing' && !MISSING_PIDS.has(d.pid)) return false;
    return true;
  });
  const s=state.sort;
  if(s==='id-asc') list.sort((a,b)=>a.pid.localeCompare(b.pid));
  else if(s==='id-desc') list.sort((a,b)=>b.pid.localeCompare(a.pid));
  else if(s==='price-asc') list.sort((a,b)=>(a.priceN||Infinity)-(b.priceN||Infinity));
  else if(s==='price-desc') list.sort((a,b)=>(b.priceN||-Infinity)-(a.priceN||-Infinity));
  else if(s==='dims-asc') list.sort((a,b)=>(a.vol||Infinity)-(b.vol||Infinity));
  else if(s==='dims-desc') list.sort((a,b)=>(b.vol||-Infinity)-(a.vol||-Infinity));
  else if(s==='year-desc') list.sort((a,b)=>String(b.launchYear).localeCompare(String(a.launchYear)));
  return list;
}
function render(){
  state.list = getFiltered();
  const totalPages = Math.max(1, Math.ceil(state.list.length/state.perPage));
  if(state.page>totalPages) state.page=totalPages;
  const start=(state.page-1)*state.perPage;
  const pageItems = state.list.slice(start,start+state.perPage);
  document.getElementById('resultCount').textContent = `共 ${state.list.length} 件`;
  const grid=document.getElementById('grid');
  if(pageItems.length===0){
    grid.innerHTML='<div class="empty"><div class="icon">◌</div><div>沒有符合條件的作品</div></div>';
  } else {
    grid.innerHTML = pageItems.map((d,i)=>{
      const realIdx=start+i;
      const tags = (d.pid?`<span class="tag pid">${d.pid}</span>`:'')+
        (d.limitQty!=null&&d.limitQty>0?`<span class="tag limit">限量 ${d.limitQty}</span>`:'');
      const stockTxt = (d.stock!=='NA') ? `<span class="stock in">數量 ${d.stock}</span>` : '';
      const collBadge = (d.stockN>=1) ? '<span class="coll-badge">典藏</span>' : '';
      return `<div class="card" data-idx="${realIdx}">
        <div class="thumb"><img loading="lazy" src="${IMG_BASE+encodeURI(d.name)}" alt="${d.prodName}" onerror="this.parentElement.innerHTML='<div style=&quot;display:flex;align-items:center;justify-content:center;height:100%;color:#aaa;font-size:12px&quot;>載入失敗</div>'"></div>
        <div class="meta">
          <div class="tagrow">${collBadge}<div class="tags">${tags}</div></div>
          <div class="pname">${d.prodName}</div>
          <div class="prow">${d.prodPrice?`<div class="price">${d.prodPrice}</div>`:''}${stockTxt}</div>
          <div class="dims">${d.dims!=='NA'?('長寬高 '+d.dims):''}${d.launchYear!=='NA'?(' · '+d.launchYear+' 上市'):''}</div>
        </div>
      </div>`;
    }).join('');
    grid.querySelectorAll('.card').forEach(c=>{c.onclick=()=>openLB(parseInt(c.dataset.idx));});
  }
  renderPagination(totalPages);
}
function renderPagination(totalPages){
  const pg=document.getElementById('pagination');
  if(totalPages<=1){pg.innerHTML='';return;}
  let h=`<button class="page-btn" ${state.page===1?'disabled':''} data-p="${state.page-1}">‹</button>`;
  let s=Math.max(1,state.page-3),e=Math.min(totalPages,state.page+3);
  if(s>1){h+=`<button class="page-btn" data-p="1">1</button>`;if(s>2)h+='<span style="align-self:center;color:#9a8768">…</span>';}
  for(let p=s;p<=e;p++)h+=`<button class="page-btn ${p===state.page?'active':''}" data-p="${p}">${p}</button>`;
  if(e<totalPages){if(e<totalPages-1)h+='<span style="align-self:center;color:#9a8768">…</span>';h+=`<button class="page-btn" data-p="${totalPages}">${totalPages}</button>`;}
  h+=`<button class="page-btn" ${state.page===totalPages?'disabled':''} data-p="${state.page+1}">›</button>`;
  pg.innerHTML=h;
  pg.querySelectorAll('.page-btn').forEach(b=>{if(b.dataset.p)b.onclick=()=>{state.page=parseInt(b.dataset.p);render();window.scrollTo({top:0,behavior:'smooth'});};});
}
let lbIdx=0, lbMode='prod';
function openLB(idx){lbIdx=idx;lbMode='prod';updateLB();document.getElementById('lightbox').classList.add('open');}
function updateLB(){
  const d=state.list[lbIdx];if(!d)return;
  document.getElementById('lbImg').src=IMG_BASE+encodeURI(d.name);
  const tags = (d.officialCat?`<span>分類 ${d.officialCat}${d.officialSub?'/'+d.officialSub:''}</span>`:'')+
    (d.theme?`<span>主題 ${d.theme}</span>`:'')+
    (d.pid?`<span>編號 ${d.pid}</span>`:'')+
    (d.stock!=='NA'?`<span>數量 ${d.stock}</span>`:'');
  document.getElementById('lbInfo').innerHTML=`
    <div class="lb-name">${d.prodName}</div>
    ${d.prodPrice?`<div class="lb-price">${d.prodPrice}</div>`:''}
    <div class="lb-row">
      ${tags}
      ${d.dims!=='NA'?`<span>尺寸 ${d.dims}</span>`:''}
      ${d.launchYear!=='NA'?`<span>${d.launchYear} 上市</span>`:''}
    </div>
    ${(d.themeTags&&d.themeTags.length)?`<div class="lb-row"><span>標籤 ${d.themeTags.join('、')}</span></div>`:''}
    ${d.prodUrl?`<div class="lb-link"><a href="${d.prodUrl}" target="_blank">查看官網產品頁 ↗</a></div>`:''}`;
}
document.getElementById('lbClose').onclick=()=>document.getElementById('lightbox').classList.remove('open');
document.getElementById('lightbox').onclick=e=>{if(e.target.id==='lightbox')e.currentTarget.classList.remove('open');};
function lbTotal(mode){if(mode==='print')return PRINT_FILES.length;if(mode==='xiaomao')return XIAOMAO_FILES.length;if(mode==='sanyi')return SAN_YI_FILES.length;if(mode==='ceramic')return CERAMIC_FILES.length;if(mode==='zisha')return ZISHA_FILES.length;if(mode==='teapot')return TEAPOT_FILES.length;if(mode==='s331')return S331_FILES.length;if(mode==='pottery')return POTTERY_FILES.length;if(mode==='accessory')return ACCESSORY_FILES.length;if(mode==='fengzi')return FENGZI_VIEW.length;if(mode==='archive')return ARCHIVE_DATA.length;if(mode==='yunlin')return YUNLIN_FILES.length;if(mode==='ceramist')return ceramistItems().length;return state.list.length;}
function lbBounds(mode){const g=ANGLE_GROUPS[mode];if(!g)return [0,lbTotal(mode)-1];for(const r of g){if(lbIdx>=r[0]&&lbIdx<=r[1])return r;}return [0,lbTotal(mode)-1];}
document.getElementById('lbPrev').onclick=()=>{const b=lbBounds(lbMode);if(lbIdx>b[0]){lbIdx--;lbMode==='print'?updatePrintLB():(lbMode==='xiaomao'||lbMode==='sanyi'||lbMode==='ceramic'||lbMode==='zisha'||lbMode==='teapot'||lbMode==='s331'||lbMode==='pottery'||lbMode==='yunlin'||lbMode==='fengzi'||lbMode==='archive'||lbMode==='ceramist')?(lbMode==='ceramist'?openCeramistLB(lbIdx):lbMode==='archive'?openArchiveLB(lbIdx):openCustomLB(lbIdx,lbMode)):updateLB();}};
document.getElementById('lbNext').onclick=()=>{const b=lbBounds(lbMode);if(lbIdx<b[1]){lbIdx++;lbMode==='print'?updatePrintLB():(lbMode==='xiaomao'||lbMode==='sanyi'||lbMode==='ceramic'||lbMode==='zisha'||lbMode==='teapot'||lbMode==='s331'||lbMode==='pottery'||lbMode==='yunlin'||lbMode==='fengzi'||lbMode==='archive')?(lbMode==='archive'?openArchiveLB(lbIdx):openCustomLB(lbIdx,lbMode)):updateLB();}};
function lbJump(delta){
  const gs=ANGLE_GROUPS[lbMode];
  if(!gs||!gs.length)return;
  let k=-1;
  for(let i=0;i<gs.length;i++){if(lbIdx>=gs[i][0]&&lbIdx<=gs[i][1]){k=i;break;}}
  if(k<0)return;
  const t=k+delta;
  if(t<0||t>=gs.length)return;
  lbMode==='fengzi'?openCustomLB(gs[t][0],lbMode):openCustomLB(gs[t][0],lbMode);
}
document.getElementById('lbPrevItem').onclick=()=>lbJump(-1);
document.getElementById('lbNextItem').onclick=()=>lbJump(1);

document.addEventListener('keydown',e=>{
  if(!document.getElementById('lightbox').classList.contains('open'))return;
  if(e.key==='Escape')document.getElementById('lightbox').classList.remove('open');
  if(e.key==='ArrowLeft')document.getElementById('lbPrev').click();
  if(e.key==='ArrowRight')document.getElementById('lbNext').click();
  if(e.key==='ArrowUp')document.getElementById('lbPrevItem').click();
  if(e.key==='ArrowDown')document.getElementById('lbNextItem').click();
});

