const POTTERY_BASE = '../images/pottery_classic/';
CERAMIST_ITEMS.forEach(x=>{if(x.f&&x.f.indexOf('http')!==0)x.f='../'+x.f;});
const ACCESSORY_FILES=GALLERY_DATA.files.accessory;
const ACCESSORY_BASE = '../images/accessory/';
function renderPrint(){
  document.getElementById('printCount').textContent = PRINT_FILES.length + ' 張';
  document.getElementById('printGrid').innerHTML = PRINT_FILES.map((f,i)=>`
    <div class="card print-card" data-pi="${i}">
      <div class="thumb"><img src="${PRINT_BASE+encodeURIComponent(f)}" alt="${f}" onerror="this.parentElement.innerHTML='<div style=&quot;display:flex;align-items:center;justify-content:center;height:100%;color:#aaa;font-size:12px&quot;>載入失敗</div>'"></div>
      <div class="meta"><div class="pname">${f.replace('.webp','')}</div></div>
    </div>`).join('');
  document.querySelectorAll('.print-card').forEach(c=>{c.onclick=()=>openPrintLB(parseInt(c.dataset.pi));});
}
function updatePrintLB(){
  const f=PRINT_FILES[lbIdx];
  document.getElementById('lbImg').src=PRINT_BASE+encodeURIComponent(f);
  document.getElementById('lbInfo').innerHTML=`<div class="lb-name">${f.replace('.webp','')}</div><div class="lb-row"><span>類型：法藍瓷印刷</span></div>`;
}

function customFiles(mode){
  if(mode==='xiaomao') return {list:XIAOMAO_FILES, base:XIAOMAO_BASE, label:'小毛石雕'};
  if(mode==='sanyi') return {list:SAN_YI_FILES, base:SAN_YI_BASE, label:'陶瓷三三藝'};
  if(mode==='ceramic') return {list:CERAMIC_FILES, base:CERAMIC_BASE, label:'陶瓷'};
  if(mode==='zisha') return {list:ZISHA_FILES, base:ZISHA_BASE, label:'紫砂壺'};
  if(mode==='teapot') return {list:TEAPOT_FILES, base:TEAPOT_BASE, label:'茶壺'};
  if(mode==='s331') return {list:S331_FILES, base:S331_BASE, label:'331'};
  if(mode==='pottery') return {list:POTTERY_FILES, base:POTTERY_BASE, label:'陶藝'};
  if(mode==='fengzi') return {list:FENGZI_FILES, base:FENGZI_BASE, label:'豐子汝窯'};
  if(mode==='accessory') return {list:ACCESSORY_FILES, base:ACCESSORY_BASE, label:'飾品文玩'};
  return {list:YUNLIN_FILES, base:YUNLIN_BASE, label:'昀林篆刻'};
}
function renderCustom(mode){
  const {list,base,label}=customFiles(mode);
  const ag=(ANGLE_GROUPS&&ANGLE_GROUPS[mode])||[];
  // 每組只留組首主圖（多角度視圖只在 lightbox 切換）；組界以原始 list 索引為準
  // fengzi 例外：FENGZI_FILES 已是 79 件主圖、組界為 VIEW 空間，直接使用
  let files=list;
  if(ag.length&&mode!=='fengzi'){
    const keep={};
    for(const g of ag) keep[g[0]]=1;
    files=list.filter((f,i)=>!!keep[i]);
  }
  if(state.q)files=files.filter(f=>f.toLowerCase().includes(state.q)||String(list.indexOf(f)+1).padStart(3,'0').includes(state.q));
  // 多角度組主圖排最前、單張在後
  if(ag.length&&mode!=='fengzi'){
    const multiHead={};
    for(const g of ag) if(g[1]>g[0]) multiHead[g[0]]=1;
    if(Object.keys(multiHead).length) files=[...files].sort((a,b)=>((multiHead[list.indexOf(b)]?1:0)-(multiHead[list.indexOf(a)]?1:0)));
  }
  const gridId = mode==='xiaomao'?'xiaomaoGrid':(mode==='sanyi'?'sanyiGrid':(mode==='ceramic'?'ceramicGrid':(mode==='zisha'?'zishaGrid':(mode==='teapot'?'teapotGrid':(mode==='s331'?'s331Grid':(mode==='pottery'?'potteryGrid':(mode==='fengzi'?'fengziGrid':(mode==='accessory'?'accessoryGrid':'yunlinGrid'))))))));
  const cntId = mode==='xiaomao'?'xiaomaoCount':(mode==='sanyi'?'sanyiCount':(mode==='ceramic'?'ceramicCount':(mode==='zisha'?'zishaCount':(mode==='teapot'?'teapotCount':(mode==='s331'?'s331Count':(mode==='pottery'?'potteryCount':(mode==='fengzi'?'fengziCount':(mode==='accessory'?'accessoryCount':'yunlinCount'))))))));
  document.getElementById(cntId).textContent = files.length + ' 件';
  document.getElementById(gridId).innerHTML = files.length?files.map((f,i)=>{
    const oi=list.indexOf(f);
    const fo=(mode==='fengzi'&&FENGZI_OFFSET&&FENGZI_OFFSET[oi]!==undefined)?((GALLERY_DATA.meta.fengzi&&GALLERY_DATA.meta.fengzi[f])||FENGZI_ITEMS[FENGZI_ITEM_OF_VIEW[FENGZI_OFFSET[oi]]]):null;
    const metaHTML = mode==='fengzi'
      ? `<div class="tagrow"><span class="tag">${fo&&fo.id?fo.id:label+' '+String(i+1).padStart(3,'0')}</span><span class="tag official">${label}</span></div><div class="pname">${fo&&fo.name?fo.name:label+' '+String(i+1).padStart(3,'0')}</div>${fo&&fo.price?'<div class="price">NT$ '+Number(fo.price).toLocaleString()+'</div>':''}${fo&&fo.spec?'<div class="dims">規格 '+fo.spec+'</div>':''}`
      : `<div class="pname">${label} ${String(i+1).padStart(3,'0')}</div>${fo&&fo.price?'<div class="price">NT$ '+Number(fo.price).toLocaleString()+'</div>':''}`;
    return `
    <div class="card" data-ci="${oi}" data-cm="${mode}">
      <div class="thumb"><img src="${base+encodeURIComponent(f)}" alt="${label} ${String(i+1).padStart(3,'0')}" onerror="this.parentElement.innerHTML='<div style=&quot;display:flex;align-items:center;justify-content:center;height:100%;color:#aaa;font-size:12px&quot;>載入失敗</div>'"></div>
      <div class="meta">${metaHTML}</div>
    </div>`}).join(''):'<div class="empty"><div class="icon">◌</div><div>沒有符合條件的作品</div></div>';
  document.querySelectorAll(`#${gridId} .card`).forEach(c=>{c.onclick=()=>{const ci=parseInt(c.dataset.ci);const cm=c.dataset.cm;openCustomLB(cm==='fengzi'?FENGZI_OFFSET[ci]:ci,cm);};});
}

function renderArchive(){
  const sel=document.getElementById('archiveCatSel');
  const cat=sel.value;
  const list=cat?ARCHIVE_DATA.filter(d=>d.cat===cat):ARCHIVE_DATA;
  document.getElementById('archiveCount').textContent=list.length+' 件';
  const grid=document.getElementById('archiveGrid');
  grid.innerHTML=list.map((d,i)=>`<div class="card" data-ci="${i}"><div class="thumb"><img src="${d.thumb}" alt="${(d.title||d.id).replace(/"/g,'&quot;')}" onerror="this.parentElement.innerHTML='<div style=&quot;display:flex;align-items:center;justify-content:center;height:100%;color:#aaa;font-size:12px&quot;>載入失敗</div>'"></div></div>`).join('');
  grid.querySelectorAll('.card').forEach(c=>c.onclick=()=>openArchiveLB(parseInt(c.dataset.ci)));
}
function openArchiveLB(i){
  const d=ARCHIVE_DATA[i];
  lbMode='archive';lbIdx=i;
  document.getElementById('lbImg').src=d.full;
  document.getElementById('lbImg').alt=d.title||d.id;
  const p=d.price?'<div style="margin-top:6px">NT$ '+d.price+'</div>':'';
  const sp=d.spec?'<div style="margin-top:2px">規格 '+d.spec+'</div>':'';
  document.getElementById('lbInfo').innerHTML='<b>'+d.id+' · '+(d.title||'')+'</b><div style="margin-top:4px;color:var(--gold-deep)">'+d.catZh+'</div>'+p+sp+(d.desc?'<div style="margin-top:10px">'+d.desc+'</div>':'');
  document.getElementById('lightbox').classList.add('open');
}
const _acs=document.getElementById('archiveCatSel');if(_acs){_acs.addEventListener('change',renderArchive);}
function openCustomLB(i,mode){
  if(mode==='fengzi'){
    lbIdx=i;lbMode='fengzi';
    const it=FENGZI_ITEMS[FENGZI_ITEM_OF_VIEW[i]]||{};
    document.getElementById('lbImg').src=FENGZI_BASE+encodeURIComponent(FENGZI_VIEW[i]);
    const b=lbBounds('fengzi');
    const pos=b?((i-b[0]+1)+'/'+(b[1]-b[0]+1)):'1/1';
    document.getElementById('lbVNav').style.display='flex';
    document.getElementById('lbInfo').innerHTML=
      `<div class="lb-name">${it.name||'豐子汝窯'}</div>`+
      (it.price?`<div class="lb-price">NT$ ${Number(it.price).toLocaleString()}</div>`:'')+
      `<div class="lb-row"><span>分類 豐子汝窯</span>${it.id?`<span>編號 ${it.id}</span>`:''}${it.spec?`<span>規格 ${it.spec}</span>`:''}<span>圖片 ${pos}</span></div>`;
    document.getElementById('lightbox').classList.add('open');
    return;
  }
  const {list,base,label}=customFiles(mode);
  lbIdx=i; lbMode=mode;
  document.getElementById('lbImg').src=base+encodeURIComponent(list[i]);
  const m=(GALLERY_DATA.meta[mode]||{})[list[i]]||{};
  const b=lbBounds(mode);
  const pos=b?((i-b[0]+1)+'/'+(b[1]-b[0]+1)):'1/1';
  const spec=m.spec||m.size||'';
  document.getElementById('lbVNav').style.display='flex';
  document.getElementById('lbInfo').innerHTML=
    `<div class="lb-name">${m.name||(label+' '+String(i+1).padStart(3,'0'))}</div>`+
    (m.price?`<div class="lb-price">NT$ ${m.price}</div>`:'')+
    `<div class="lb-row"><span>分類 ${m.cat||label}</span><span>編號 ${String(i+1).padStart(3,'0')}</span>${spec?`<span>規格 ${spec}</span>`:''}<span>圖片 ${pos}</span></div>`+
    (m.desc?`<div class="lb-desc">${m.desc}</div>`:'');
  document.getElementById('lightbox').classList.add('open');
}
function openPrintLB(i){lbIdx=i;lbMode='print';updatePrintLB();document.getElementById('lightbox').classList.add('open');}
let ceramistFilter='';
function ceramistItems(){return ceramistFilter?CERAMIST_ITEMS.filter(x=>x.a===ceramistFilter):CERAMIST_ITEMS;}
function renderCeramistChips(){
  const box=document.getElementById('ceramistChips');
  box.innerHTML='<button class="chip active" data-artist="">全部<em>'+CERAMIST_ITEMS.length+'</em></button>'+CERAMIST_ARTISTS.map(a=>'<button class="chip" data-artist="'+a.n+'">'+a.n+'<em>'+a.c+'</em></button>').join('');
  box.querySelectorAll('.chip').forEach(c=>c.onclick=()=>{box.querySelectorAll('.chip').forEach(x=>x.classList.remove('active'));c.classList.add('active');ceramistFilter=c.dataset.artist;renderCeramist();});
}
function renderCeramist(){
  let items=ceramistItems();
  if(state.q)items=items.filter(x=>x.f.toLowerCase().includes(state.q)||x.a.includes(state.q));
  document.getElementById('ceramistCount').textContent=items.length+' 件';
  const grid=document.getElementById('ceramistGrid');
  grid.innerHTML=items.length?items.map((x,i)=>`
    <div class="card" data-ci="${i}">
      <div class="thumb"><img src="${x.f}" alt="${x.a} ${String(i+1).padStart(3,'0')}" onerror="this.parentElement.innerHTML='<div style=&quot;display:flex;align-items:center;justify-content:center;height:100%;color:#aaa;font-size:12px&quot;>載入失敗</div>'"></div>
      <div class="meta"><div class="pname">${x.a} ${String(i+1).padStart(3,'0')}</div></div>
    </div>`).join(''):'<div class="empty"><div class="icon">◌</div><div>沒有符合條件的作品</div></div>';
  grid.querySelectorAll('.card').forEach(c=>c.onclick=()=>openCeramistLB(parseInt(c.dataset.ci)));
}
function openCeramistLB(i){
  const items=ceramistItems();
  lbIdx=i;lbMode='ceramist';
  document.getElementById('lbImg').src=items[i].f;
  document.getElementById('lbInfo').innerHTML=`<div class="lb-name">${items[i].a} ${String(i+1).padStart(3,'0')}</div><div class="lb-row"><span>${items[i].a}</span></div>`;
  document.getElementById('lightbox').classList.add('open');
}
(function(){
  const tabs=document.querySelectorAll('.tab');
  const prodMain=document.getElementById('prodPage');
  const printPage=document.getElementById('printPage');
  function switchPage(name){
    tabs.forEach(t=>t.classList.toggle('active',t.dataset.page===name));
    prodMain.style.display=(name==='products')?'':'none';
    printPage.style.display=(name==='print')?'':'none';
    document.getElementById('xiaomaoPage').style.display=(name==='xiaomao')?'':'none';
    document.getElementById('yunlinPage').style.display=(name==='yunlin')?'':'none';
    document.getElementById('sanyiPage').style.display=(name==='sanyi')?'':'none';
    document.getElementById('ceramicPage').style.display=(name==='ceramic')?'':'none';
    document.getElementById('zishaPage').style.display=(name==='zisha')?'':'none';
    document.getElementById('teapotPage').style.display=(name==='teapot')?'':'none';
    document.getElementById('s331Page').style.display=(name==='s331')?'':'none';
    document.getElementById('potteryPage').style.display=(name==='pottery')?'':'none';
    document.getElementById('accessoryPage').style.display=(name==='accessory')?'':'none';
    document.getElementById('fengziPage').style.display=(name==='fengzi')?'':'none';
    document.getElementById('archivePage').style.display=(name==='archive')?'':'none';
    document.getElementById('ceramistPage').style.display=(name==='ceramist')?'':'none';
    if(name==='print')renderPrint();
    if(name==='xiaomao')renderCustom('xiaomao');
    if(name==='yunlin')renderCustom('yunlin');
    if(name==='sanyi')renderCustom('sanyi');
    if(name==='ceramic')renderCustom('ceramic');
    if(name==='zisha')renderCustom('zisha');
    if(name==='teapot')renderCustom('teapot');
    if(name==='s331')renderCustom('s331');
    if(name==='pottery')renderCustom('pottery');
    if(name==='accessory')renderCustom('accessory');
    if(name==='fengzi')renderCustom('fengzi');
    if(name==='archive')renderArchive();
    if(name==='ceramist'){ceramistFilter='';renderCeramistChips();renderCeramist();}
    document.getElementById('crumbCur').textContent = name==='products'?(state.theme?('主題 · '+state.theme):'全部作品'):(name==='print'?'藝品圖鑑':(name==='ceramist'?'陶藝家':customFiles(name).label));
    document.querySelectorAll('#chips .chip').forEach(x=>x.classList.remove('active'));
    if(name==='products'){const t=document.querySelector('#chips .chip[data-theme="'+(state.theme||'')+'"]');if(t)t.classList.add('active');}
    else{const cl=document.querySelector('#chips .chip-lib[data-goto="'+name+'"]');if(cl)cl.classList.add('active');}
  }
  tabs.forEach(t=>t.onclick=()=>switchPage(t.dataset.page));
  window.switchPage=switchPage;
})();


/* ===== 子資料夾獨立頁引導（主站 index.html 不載入此段） ===== */
const PAGE_FOLDER={products:'產品圖庫',archive:'典藏',print:'藝品圖鑑',xiaomao:'小毛石雕',yunlin:'昀林篆刻',sanyi:'陶瓷三三藝',ceramic:'陶瓷',zisha:'紫砂壺',teapot:'茶壺',s331:'331',pottery:'陶藝',accessory:'飾品文玩',fengzi:'豐子汝窯',ceramist:'陶藝家'};
function initPage(mode){
  document.querySelectorAll('.tabs .tab').forEach(t=>{
    t.onclick=()=>{const k=t.dataset.page;if(k&&PAGE_FOLDER[k]){location.href='../'+PAGE_FOLDER[k]+'/index.html';}};
    if(t.dataset.page===mode){t.classList.add('active');}else{t.classList.remove('active');}
  });
  document.querySelectorAll('.mega-item[data-goto]').forEach(a=>{
    a.onclick=(e)=>{e.preventDefault();const k=a.dataset.goto;if(PAGE_FOLDER[k]){location.href='../'+PAGE_FOLDER[k]+'/index.html';}};
    if(a.dataset.goto===mode){a.classList.add('active');}else{a.classList.remove('active');}
  });
  const ms=document.getElementById('megaCeramistSel');
  if(ms){ms.onchange=()=>{location.href='../陶藝家/index.html';};}
  document.querySelectorAll('.mega-item[data-goto]').forEach(a=>{
    const k=a.dataset.goto;
    if(k==='archive'){const n=document.getElementById('archiveCount');const c=a.querySelector('.mega-count');if(c&&n)c.textContent=(n.textContent||'0')+' 件';}
  });
  if(mode==='print'){renderPrint();}
  else if(mode==='xiaomao'){renderCustom('xiaomao');}
  else if(mode==='yunlin'){renderCustom('yunlin');}
  else if(mode==='sanyi'){renderCustom('sanyi');}
  else if(mode==='ceramic'){renderCustom('ceramic');}
  else if(mode==='zisha'){renderCustom('zisha');}
  else if(mode==='teapot'){renderCustom('teapot');}
  else if(mode==='s331'){renderCustom('s331');}
  else if(mode==='pottery'){renderCustom('pottery');}
  else if(mode==='accessory'){renderCustom('accessory');}
  else if(mode==='fengzi'){renderCustom('fengzi');}
  else if(mode==='archive'){renderArchive();}
  else if(mode==='ceramist'){ceramistFilter='';renderCeramistChips();renderCeramist();}
}
